WITH base AS (SELECT toStartOfDay(toDateTime64(sessionization_sessions.session_start, 9, 'UTC')) AS `period`, COUNT(sessionization_sessions.user_id) AS `sessions`, COUNT(DISTINCT sessionization_sessions.user_id) AS `users`, AVG(sessionization_sessions.duration_seconds) AS `avgDurationSeconds`, AVG(sessionization_sessions.event_count) AS `avgEventsPerSession` FROM sessionization_sessions WHERE toDateTime64(sessionization_sessions.session_start, 9, 'UTC') BETWEEN ? AND ? GROUP BY `period`) SELECT `period`, `sessions`, `users`, (toFloat64(`sessions`) / NULLIF(`users`, 0)) AS `sessionsPerUser`, `avgDurationSeconds`, `avgEventsPerSession` FROM base ORDER BY `period` ASC
